CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, name VARCHAR(60) NOT NULL, email VARCHAR(254) NOT NULL, password_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower_uq ON users (LOWER(email));
CREATE TABLE IF NOT EXISTS oauth_accounts (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider VARCHAR(20) NOT NULL, provider_user_id VARCHAR(200) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(provider, provider_user_id));
CREATE TABLE IF NOT EXISTS user_data (user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, data_key VARCHAR(80) NOT NULL, data_value TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(user_id,data_key));
CREATE TABLE IF NOT EXISTS sessions (sid VARCHAR(200) PRIMARY KEY, sess TEXT NOT NULL, expire_at TIMESTAMPTZ NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expire_idx ON sessions(expire_at);
